contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address key) public {
        require(key != address(0), "key must be nonzero");

        uint256 beforeKeyBalance = c.balances(key); if (__ESBMC_reverted()) return;
        require(beforeKeyBalance == 0, "key balance must be zero before the call");

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterKeyBalance = c.balances(key); if (__ESBMC_reverted()) return;
        assert(afterKeyBalance == 0);
    }
}

