// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address key) internal {
        vm.assume(key != address(0));
        uint256 beforeKeyBalance;
        try c.balances(key) returns (uint256 __r) { beforeKeyBalance = __r; } catch { return; }
        vm.assume(beforeKeyBalance == 0);
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterKeyBalance;
        try c.balances(key) returns (uint256 __r) { afterKeyBalance = __r; } catch { return; }
        assertTrue(afterKeyBalance == 0);
    }

    function testFuzz_run(address key) public {
        vm.assume(key.code.length == 0 && uint160(key) > 0xffff && key != address(this) && key != address(c) && key != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && key != 0x000000000000000000636F6e736F6c652e6c6f67 && key != 0x4e59b44847b379578588920cA78FbF26c0B4956C && key != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(key);
    }

    receive() external payable {}
}
